"""
Centralized embedded asset module.
All binary brand assets (logo, favicon variants) are stored here ONCE as
Base64 data URIs and imported wherever needed (Jinja context processor,
manifest, etc.) so the same encoded string is never duplicated across
templates or files.
"""

LOGO_MAIN = "data:image/webp;base64,"   # 512x512 - hero / about / footer
LOGO_SMALL = "data:image/webp;base64,"  # 128x128 - navbar
FAVICON_64 = "data:image/png;base64,"    # 64x64 - favicon
FAVICON_32 = "data:image/png;base64,"    # 32x32 - favicon
